def max_sum(arr, n):
    """Write a function to find the maximum sum of bi-tonic sub-sequence for the given array."""
    if not arr or n is None or n <= 0:
        return 0
    n = min(n, len(arr))
    if n <= 0:
        return 0
    a = list(arr[:n])
    inc = a[:]
    for i in range(n):
        for j in range(i):
            if a[j] < a[i] and inc[j] + a[i] > inc[i]:
                inc[i] = inc[j] + a[i]
    dec = a[:]
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if a[j] < a[i] and dec[j] + a[i] > dec[i]:
                dec[i] = dec[j] + a[i]
    return max(inc[i] + dec[i] - a[i] for i in range(n))
